android.extraProguardRules:
# react-native-reanimated: JNI and TurboModule classes are called by reflection. R8 removes them and animations crash in release.
-keep class com.swmansion.reanimated.** { *; }
-keep class com.facebook.react.turbomodule.** { *; }
-keep class com.facebook.react.fabric.** { *; }

# react-native-worklets: Reanimated 4 runs worklets through this package. R8 strips the JNI entry points.
-keep class com.swmansion.worklets.** { *; }

# @react-native-google-signin: the native module and Play Services sign-in types are loaded by name. R8 drops them and Google sign-in crashes in release.
-keep class com.reactnativegooglesignin.** { *; }
-keep class com.google.android.gms.auth.** { *; }
-keep class com.google.android.gms.auth.api.signin.** { *; }
-keep class com.google.android.gms.common.api.** { *; }

# @supabase/supabase-js is JavaScript bundled by Metro. R8 never sees it, so it has no Java keep rule.

# expo-notifications: the library keep file is not applied as consumer rules. Android creates the Firebase messaging service from the manifest.
-keep class expo.modules.notifications.** { *; }

# react-native-svg: native view classes are created by name. R8 removes them and SVG renders blank.
-keep public class com.horcrux.svg.** { *; }

# react-native-maps: ships no consumer rules. Map views and markers are created by reflection.
-keep class com.rnmaps.** { *; }

# react-native-gesture-handler: handler classes are created by name and ship no consumer rules.
-keep class com.swmansion.gesturehandler.** { *; }

# react-native-screens: screen and fragment classes are restored by name. R8 breaks navigation in release.
-keep class com.swmansion.rnscreens.** { *; }

# react-native-webview: the view manager and message events are reached by reflection.
-keep class com.reactnativecommunity.webview.** { *; }

# @react-native-async-storage/async-storage: the storage module is looked up by name.
-keep class com.reactnativecommunity.asyncstorage.** { *; }

# react-native-safe-area-context: inset views are created by name. Edge-to-edge padding depends on them.
-keep class com.th3rdwave.safeareacontext.** { *; }

# @react-native-community/datetimepicker: picker modules are created by name and ship no ProGuard rules.
-keep class com.reactcommunity.rndatetimepicker.** { *; }

# expo-task-manager: its keep rule is not wired as a consumer file. Background tasks are started by class name.
-keep class expo.modules.taskManager.** { *; }

# Google Sign-In, Reanimated, and Expo find classes through annotations and generic signatures.
-keepattributes *Annotation*,Signature,InnerClasses,EnclosingMethod
